// Literal port of the team's Casa3DSDK (module lot/terrain). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installLotTerrain(K: Kernel, shared: Shared): void {
  const { rectsOf, MIRRORS, PARTS, bx, cursor } = K;
  // ---------------- 40 lot and roofs ----------------
  // ===== lot: terrain, walls and tops, gates, roofs =====
  function terrain() {
    PARTS.length = 0; MIRRORS.length = 0; K.CARS.length = 0; shared.partCount = 0; shared.ctx.parts = {}; shared.tapCount = 0; shared.ctx.clotheslines = [];
    if (shared.ctx.noTerrain) return; // opts.terrain === false: the app already has ground, street and lawn
    const R = shared.ctx.r, lt = R.lot, C = shared.ctx.colors; cursor.group = 'floor';
    const light = (c, f) => { const m = k => Math.round(((c >> k) & 255) * (1 - f) + 255 * f); return (m(16) << 16) | (m(8) << 8) | m(0); };
    bx('grass', -150, -0.5, -150, 170, -0.1, 170, light(C.lawn != null ? C.lawn : 0x7aa84a, 0.72)); // back lawn, subtle texture
    if (lt) {
      const [u0, v0, u1, v1] = lt.rect;
      bx('sidewalk', u0, -0.09, v0, u1, -0.03, v1, 0xdedad2); // lot base (the floor zones come on top)
      bx('asphalt', u0 - 40, -0.09, v0 - 9, u1 + 40, -0.03, v0 - 1.8, 0x8d9096); // street
      bx('sidewalk', u0 - 40, -0.06, v0 - 1.8, u1 + 40, 0.02, v0, 0xe4e0d6); // sidewalk
      for (let x = u0 - 38; x < u1 + 40; x += 6) bx('plaster', x, 0, v0 - 5.6, x + 2.6, 0.005, v0 - 5.4, 0xe8e4b8); // centre line
    } else {
      const b = shared.ctx.limits; bx('sidewalk', b.x0 - 6, -0.09, b.z0 - 6, b.x1 + 6, -0.03, b.z1 + 6, 0xdedad2);
    }
  }
  // R63: stretches [x0,x1] of the wall segment (axis a..b on line L) that do NOT go through a room of the house (room wall against the lot wall)
  function freeSpans(alongU, L, a, b) {
    const blocks = [];
    for (const c of shared.ctx.r.rooms) { if (c.type === 'void' || c.floor < 0) continue;
      for (const [u0, v0, u1, v1] of rectsOf(c)) { const c0 = alongU ? v0 : u0, c1 = alongU ? v1 : u1, lo = alongU ? u0 : v0, hi = alongU ? u1 : v1; if (L >= c0 - 0.3 && L <= c1 + 0.3 && hi > a && lo < b) blocks.push([lo - 0.3, hi + 0.3]); } }
    blocks.sort((p, q) => p[0] - q[0]); const out = []; let x = a;
    for (const [lo, hi] of blocks) { if (lo > x) out.push([x, Math.min(lo, b)]); x = Math.max(x, hi); if (x >= b) break; }
    if (x < b) out.push([x, b]); return out.filter(q => q[1] - q[0] > 0.3);
  }
  Object.assign(K, { terrain, freeSpans });
}
